// ── EDIT THE PROMPT HERE ──────────────────────────────────────────
// The backend posts { case_id, entities, edges, gemini_key, model }.
// entities/edges are already credential-sanitised backend-side.
const body = $json.body || $json;
const entities = (body.entities || []).map(e => ({ id: e.id, type: e.entity_type, label: e.label, data: e.data }));
const edges = (body.edges || []).map(e => ({ from: e.from_entity, to: e.to_entity, relation: e.relation_type }));

const SYSTEM = `You are an OSINT analyst assistant for a law-enforcement case tool.
Given a case graph (entities + edges), do THREE things, grounded ONLY in the provided data:
1) identity_clusters: which entities most likely belong to the SAME real person/actor, with a short rationale and a 0-1 confidence;
2) suggested_edges: plausible NEW relationships between EXISTING entities (never invent entities), each with relation, rationale, confidence;
3) narrative: a concise attribution summary + next_steps (which selectors are worth pursuing).
Never fabricate. If evidence is weak, say so. Respond ONLY as JSON:
{"identity_clusters":[{"entity_ids":[],"rationale":"","confidence":0}],"suggested_edges":[{"from_id":"","to_id":"","relation":"","rationale":"","confidence":0}],"narrative":"","next_steps":[]}`;

const prompt = SYSTEM + `\n\nENTITIES:\n` + JSON.stringify(entities, null, 1) + `\n\nEDGES:\n` + JSON.stringify(edges, null, 1);

const geminiBody = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { responseMimeType: "application/json", temperature: 0.2 }
};

return [{ json: {
  case_id: body.case_id || null,
  model: body.model || "gemini-2.0-flash",
  gemini_key: body.gemini_key || "",
  gemini_body: geminiBody
} }];

// Gemini returns candidates[0].content.parts[0].text = the JSON string.
// On an API error (quota/404/…) it returns { error: {...} } — surface it.
const r = $json;
if (r && r.error) {
  return [{ json: { error: 'Gemini: ' + (r.error.message || JSON.stringify(r.error)), code: r.error.code } }];
}
let text = '';
try { text = r.candidates[0].content.parts[0].text; } catch (e) { text = ''; }
let parsed = {};
try { parsed = JSON.parse(text); } catch (e) { parsed = { error: 'model did not return valid JSON', raw: text }; }
// Pass through the exact token usage so the platform can account it.
const u = r.usageMetadata || {};
parsed._usage = { prompt: u.promptTokenCount || 0, output: u.candidatesTokenCount || 0, total: u.totalTokenCount || 0 };
return [{ json: parsed }];
